<june-make-room id="{{ hero_id }}" class="jh{% if settings.june_type_enabled != false and master_type_block.settings.use_master_typography != false %} june-type{% endif %}" data-text-motion="{{ typography.motion_enabled | default: true, allow_false: true }}" data-motion-speed="{{ typography.motion_speed | default: 100 }}" data-motion-plays="{{ typography.motion_plays | default: 1 }}" data-motion-loop="{{ typography.motion_loop | default: false }}" data-motion-gap="{{ typography.motion_gap | default: 4 }}" aria-label="{{ 'june_hero.labels.region' | t | escape }}">
