{% schema %}
{
  "name": "June · Make Room",
  "tag": "section",
  "class": "june-make-room-section",
  "enabled_on": {
    "templates": [
      "index"
    ]
  },
  "max_blocks": 10,
  "settings": [
    {
      "type": "header",
      "content": "Copy"
    },
    {
      "type": "text",
      "id": "eyebrow",
      "label": "Eyebrow",
      "default": "The planner edit"
    },
    {
      "type": "text",
      "id": "heading",
      "label": "Heading",
      "default": "Make room."
    },
    {
      "type": "textarea",
      "id": "subheading",
      "label": "Subheading",
      "default": "For big plans. And\neveryday ones."
    },
    {
      "type": "text",
      "id": "body",
      "label": "Supporting text",
      "default": "Start any day. Make it yours."
    },
    {
      "type": "header",
      "content": "Planner imagery"
    },
    {
      "type": "image_picker",
      "id": "hero_image",
      "label": "Optional complete desktop artwork"
    },
    {
      "type": "checkbox",
      "id": "desktop_scene",
      "label": "Desktop artwork includes full background",
      "default": false,
      "info": "Places wide artwork behind editable text on large screens. Use a portrait mobile image."
    },
    {
      "type": "image_picker",
      "id": "hero_image_mobile",
      "label": "Optional complete mobile artwork"
    },
    {
      "type": "text",
      "id": "hero_alt",
      "label": "Complete artwork description",
      "default": "Undated planners and an open planner spread"
    },
    {
      "type": "image_picker",
      "id": "cover_left",
      "label": "Left cover"
    },
    {
