 .ju.ju--type-preview .ju__primary,.ju.ju--type-preview .ju__textlink,.ju.ju--type-preview .ju__toggles,.ju.ju--type-preview .ju__caption,.ju.ju--type-preview .ju__policies,.ju.ju--type-preview .jphoto__open>span{font-size:var(--preview-small-mobile)!important}

